    [10] = {s = {["|1"] = "After completing Even More Gullible's Travels you will have a scent of the Rafflesia flowers on you.", ["|2"] = "Speak to Gatih Mijurabi (I-8) to begin this quest to remove the scent.", ["|3"] = "The hot springs is located in Korroloka Tunnel (G-9) on map 4.", ["|4"] = "Stand yourself under the waterfall for approximately 5 minutes.", ["|5"] = "The waterfall is guarded by several leeches that aggro to level 99 players.", ["|6"] = "Return to Gatih Mijurabi to complete the quest."}},
