    [12] = {s = {["|1"] = "Speak with Ronta-Onta to obtain quest.", ["|2"] = "Travel to Yhoator Jungle and look for the entrance to Ifrit's Cauldron at (I-6).", ["|3"] = "Defeat Ifrit Prime and you will receive a key item: Whisper of flames", ["|4"] = "Return to Ronta-Onta with the whisper and he will provide several reward options including the ability to summon Ifrit (Avatar)."}},
    [13] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|10"] = "This fight is against Baronial Bat.", ["|11"] = "Go back and speak with Jakoh Wahcondalo to receive your reward.", ["|2"] = "Speaking with Jakoh Wahcondalo (J-9, house next to the HP) will grant you the Weapons Training Guide as well as the Dagger of Trials.", ["|6"] = "Trade the Dagger of Trials back to Jakoh Wahcondalo.", ["|7"] = "Take Silent Oils and Prism Powders with you and head to Gustav Tunnel.", ["|8"] = "Head north and hug the east wall.", ["|9"] = "The spawn is near the intersection of (I-9) and (J-9)"}},
    [15] = {s = {["|1"] = "Speak with Dodmos in Kazham (J-9) to begin quest and obtain a Mini Tuning Fork of Fire.", ["|2"] = "You may prepare for the upcoming battle and whenever you are ready, trade Dodmos the tuning fork to be transported to the arena.", ["|3"] = "Trade the fork to the Fire Protocrystal to enter the fighting arena.", ["|4"] = "Defeat Ifrit Prime to complete quest."}},
    [100] = {s = {["|1"] = "Speak to Kieran in Norg (I-8) to receive a cutscene and the Key Item Ashen stratum abyssite.", ["|2"] = "Speak with the following NPCs to begin their respective subquests:", ["|3"] = "Complete both subquests and return to Kieran to complete the quest."}},
    [101] = {s = {["|1"] = "After starting Voidwatch Ops: Border Crossing and receiving the Ashen stratum abyssite, speak to Hildegard in Kazham to begin the Quest.", ["|2"] = "Engage in and complete the 3 Tier I Voidwatch battles in the Elshimo region:", ["|3"] = "Return to Hildegard to complete the Quest."}},
    [103] = {s = {["|1"] = "Talk to Kieran after completing Voidwatch Ops: Border Crossing.", ["|2"] = "Speak to Gilgamesh in Norg for a cutscene.", ["|3"] = "Return to Kieran for a cutscene and to receive your Ashen stratum abyssite II (the quest is flagged at this point).", ["|4"] = "Engage in and complete the three Tier II Voidwatch battles in the Li'Telor region:", ["|5"] = "Return to Kieran, which will automatically finish this quest, reward you with Ashen stratum abyssite III, and begin the next quest."}},
    [104] = {s = {["|1"] = "After completing VW Op. 115: Li'Telor Variant and receiving the Ashen stratum abyssite III from Kieran, this quest is automatically flagged.", ["|2"] = "Engage in and complete the 3 Tier III Voidwatch battles in the Tu'Lia region:", ["|3"] = "After defeating all 3, return to Norg and speak to Kieran at (H-8).", ["|4"] = "Return to Norg and speak to Gilgamesh to complete the quest."}},
    [129] = {s = {["|1"] = "Speak to Jaucribaix in Norg (K-8), near the Captain's Chamber, to begin the quest.", ["|10"] = "The Mumeito is required to do the AF1 quest: The Sacred Katana.", ["|2"] = "Speak to Aeka (I-8) to receive Oriental Steel.", ["|3"] = "Speak to Ranemaud (I-7) to receive a Sacred Sprig.", ["|4"] = "Travel to Konschtat Highlands (D-8), trade the Oriental Steel to the ??? inside the cave to spawn a Bomb Notorious Monster named Forger,", ["|5"] = "Once the Forger is defeated, a Bomb Steel will drop.", ["|6"] = "Purchase a Hatchet and travel to The Sanctuary of Zi'Tah.", ["|7"] = "Once the Treant is defeated, trade the Sacred Sprig to the ??? to receive a Sacred Branch.", ["|8"] = "Trade the Bomb Steel and the Sacred Branch to Jaucribaix.", ["|9"] = "Return in 72 in-game hours (3 real-life hours) to receive your reward."}},
    [130] = {s = {["|1"] = "Speak to Muzaffar to begin the quest.", ["|2"] = "Bring him either 4 Eastern Pottery, 4 Northern Fur, or 4 Southern Mummy to complete the quest:", ["|3"] = "All the required items can be found on the Auction House as well, under Others > Misc. 1."}},
    [131] = {s = {["|1"] = "Speak to Mamaulabion at (G-6) in Norg to activate the quest (this does not need to be done before obtaining the seven items).", ["|2"] = "Obtain the following seven items by selecting them as your reward after defeating the seven avatars below in the battles listed below", ["|3"] = "Return all seven items to Mamaulabion (the items must be traded one at a time and it is not necessary to turn in all seven at once).", ["|4"] = "Wait until midnight (JST), then speak with Mamaulabion once more to receive the Evoker's Ring.", ["|5"] = "This quest is only repeatable if Evoker's Ring is dropped."}},
    [132] = {s = {["|1"] = "Travel to Norg and enter the Buccaneer's Quarters at (J-8).", ["|2"] = "Talk to Washu.", ["|3"] = "Washu will give you an Empty Barrel.", ["|4"] = "You will need to examine a ??? that spawns randomly in Yhoator Jungle.", ["|5"] = "Once you find the ??? the Empty Barrel will turn into a Barrel of Opo-Opo brew.", ["|6"] = "Return to Washu to complete the quest."}},
    [133] = {s = {["|1"] = "Speak with Edal-Tahdal to obtain quest.", ["|10"] = "You can save yourself a lot of time traveling to the Cloister by using the Mini Fork of Wtr. given by the quest Trial-Size Trial by Water.", ["|11"] = "You may also choose to retain the whisper in order to complete the requirements for this quest: The Moonlit Path.", ["|2"] = "Travel to Yhoator Jungle and look for the entrance to Temple of Uggalepih at (J-12).", ["|3"] = "Defeat Leviathan Prime and you will receive a Whisper of tides", ["|4"] = "Return to Edal-Tahdal with the whisper and he will provide several reward options including the ability to summon Leviathan (Avatar).", ["|5"] = "Up to 6 party members can enter the arena.", ["|6"] = "Each party member must have their own Tuning fork of water.", ["|7"] = "Time limit is 30 minutes.", ["|8"] = "You can only select one of the rewards Edal-Tahdal offers at any time.", ["|9"] = "You may repeat this quest once per Earth day."}},
    [134] = {s = {["|1"] = "Speak to Magephaud in Norg (I-8) to begin the quest.", ["|2"] = "Trade him 3 Gold Beastcoins to receive the Tonberry key (Zilart).", ["|3"] = "Check with Magephaud in Norg to see if he requests the 3 Gold Beastcoins to be sure.", ["|4"] = "If Magephaud requests the beastcoins, then you should receive the Tonberry key (Zilart) to reset hate after providing the 3 Gold Beastcoins"}},
    [135] = {s = {["|1"] = "To begin this quest you first need a Damp Scroll.", ["|2"] = "You need to have the Damp Scroll in your inventory when you speak to Shivivi to begin this quest.", ["|3"] = "Take the scroll to Horlais Peak (Hot Springs side) and trade it to the Hot Springs there.", ["|4"] = "This will transform the scroll into a Jubaku: Ichi (Scroll)."}},
    [136] = {s = {["|1"] = "Speak to Laisrean in Norg at (H-7) to begin this quest.", ["|10"] = "Return to Laisrean for your reward.", ["|2"] = "Exit Norg into Sea Serpent Grotto.", ["|3"] = "Head South until you reach the fork at (H-6), head East.", ["|4"] = "Turn South at (J-5).", ["|5"] = "Head East at (J-10).", ["|6"] = "Turn East at (K-12)", ["|7"] = "Go past the Silver Door at (N-14).", ["|8"] = "Fall off the path to the one below at (H-8) and continue going North.", ["|9"] = "Follow this path until you find the ??? at (H-3)."}},
    [137] = {s = {["|1"] = "Speak to Keal (H-8) to begin this quest.", ["|2"] = "Exit Norg into Sea Serpent Grotto.", ["|3"] = "Once in Sea Serpent Grotto head South until you reach (H-7), go West from there.", ["|4"] = "Turn South at (F-7) and continue West, follow the path as it turns North at (B-7).", ["|5"] = "The ??? you're looking for is in the room at (C-5).", ["|6"] = "Examine the ??? to get the Key Item Sealed iron box.", ["|7"] = "Return to Keal to complete the quest."}},
    [138] = {s = {["|1"] = "Speak to Heiji in Norg at (I-7) to begin the quest.", ["|2"] = "Trade him 10 Rusty Subligaria to receive your reward."}},
    [139] = {s = {["|1"] = "Speak to Heizo in Norg at (H-7) to begin the quest.", ["|2"] = "Trade him 10 pairs of Rusty Leggings to receive your reward."}},
    [140] = {s = {["|1"] = "Go to Norg and talk to Jaucribaix at (K-8) near the Captain's Chamber while on Samurai to initiate the quest.", ["|2"] = "Travel to the The Sanctuary of Zi'Tah.", ["|3"] = "Trade the Fish Bait to the ??? at (E-8) to pop Isonade, a fish NM.", ["|4"] = "Re-examine the ??? to obtain the Handful of crystal scales.", ["|5"] = "Return to Norg and trade your Mumeito to Jaucribaix to complete the quest."}},
    [141] = {s = {["|1"] = "Speak to Jaucribaix in Norg (K-8)", ["|10"] = "Speak to Jaucribaix to receive your reward", ["|2"] = "Speak to Washu at (J-8)", ["|3"] = "Trade Washu Bastore Sardine, Frost Turnip, Giant Sheep Meat, and Hecteyes Eye to receive the key item Washu's tasty wurst.", ["|4"] = "Examine the ??? in Labyrinth of Onzozo (F-8) to spawn the Notorious Monster Ubume.", ["|5"] = "Examine the ??? after defeating Ubume to receive the key item Yomotsu feather.", ["|6"] = "Return to Norg and speak to to Jaucribaix.", ["|7"] = "Exit Norg, re-enter, and speak to Jaucribaix to receive the key item Yomotsu Hirasaka.", ["|8"] = "Examine the ??? in Valkurm Dunes at (B-7) between 18:00 and 4:00 to spawn the Notorious Monsters Doman and Onryo.", ["|9"] = "Examine the ??? after defeating Doman and Onryo and their corpses dissappear to receive the key item Faded Yomotsu Hirasaka."}},
    [142] = {s = {["|1"] = "Speak with Jaucribaix in Norg (K-8) to begin the quest.", ["|10"] = "Trade a Gold Thread to Jaucribaix.", ["|11"] = "Zone out of Norg, then return to Jaucribaix for your reward.", ["|2"] = "Speak to Sanosuke in Port Jeuno (H-8).", ["|3"] = "Speak to Phoochuchu in Mhaura (H-8) (ground level; under the bridge).", ["|4"] = "Examine the door on the lower level in Bastok Mines (J-6).", ["|5"] = "Enter the Waughroon Shrine through the Palborough Mines top floor.", ["|6"] = "Speak to Jaucribaix in Norg to receive a Banishing Charm.", ["|7"] = "Trade the Banishing Charm to the Burning Circle in Waughroon Shrine to begin a BC fight.", ["|8"] = "After defeating the demons, you will receive the key item Charred helm.", ["|9"] = "Speak to Jaucribaix, he will request a Gold Thread."}},
    [143] = {s = {["|1"] = "Talk to Ryoma at (H-8) in Norg (Home Point #1) to begin the quest, then head to Port Bastok", ["|2"] = "Speak to Kagetora inside Warehouse #2 at (F-6) (Port Bastok Home Point #3).", ["|3"] = "Head to (I-5) in Port Bastok and speak with Ensetsu.", ["|4"] = "After speaking with Ensetsu, make your way to (H-5)/(H-6) of Eastern Altepa Desert.", ["|5"] = "Clear the area and examine the ??? once ready.", ["|6"] = "Two non-sleepable Spider NMs called Tsuchigumo will spawn.", ["|7"] = "Clicking the ??? again after defeating the Tsuchigumo will grant the Trick box.", ["|8"] = "Head back to Norg and speak with Ryoma to complete the quest and receive your reward."}},
    [144] = {s = {["|1"] = "Travel to Norg and speak with Ryoma to receive the quest.", ["|2"] = "Talk to Ensetsu in Port Bastok at (I-5), who tells you to speak with Leodarion.", ["|3"] = "Head to Rabao and talk to Leodarion at (F-8) on the west side of the lake near the windmill.", ["|4"] = "Leodarion will request an Oak Pole, which is purchasable via Sparks from a Records of Eminence NPC:", ["|5"] = "After trading it to him, speak to Leodarion again on the next Vana'diel day.", ["|6"] = "Once in Mhaura, take the ferry to Selbina so that you will be traveling at nighttime.", ["|7"] = "The NM Enagakure will spawn on the main deck.", ["|8"] = "Once you have defeated Enagakure, make sure you have at least one inventory slot free and wait until the ferry docks in Selbina.", ["|9"] = "You will receive a cutscene, Ninja Hakama, and the quest will be complete."}},
    [145] = {s = {["|1"] = "Speak with Ryoma in Norg to begin the quest.", ["|11"] = "After the Sahagin are defeated, examine the ??? again to receive the Old trick box.", ["|12"] = "Return to Ryoma for another cutscene.", ["|13"] = "Head to Rabao and speak with Leodarion at (F-7) on the west side of the lake near the windmill.", ["|14"] = "Go to Kuftal Tunnel and obtain a Kuftal Coffer Key.", ["|16"] = "Find and open the Treasure Coffer to obtain the Large trick box.", ["|17"] = "Return to Leodarion to complete the quest.", ["|2"] = "Travel to (I-7) in Yhoator Jungle.", ["|5"] = "Once prepared, examine the ??? at (I-7) (northwest of Bloodlet Spring) to spawn 3 Sahagin NMs.", ["|6"] = "These mobs are:"}},
    [146] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|10"] = "Go back and speak with Jaucribaix to receive your reward.", ["|2"] = "Speaking with Jaucribaix will grant you the key item Weapons Training Guide as well as the Tachi of Trials.", ["|6"] = "Trade the Tachi of Trials back to Jaucribaix.", ["|7"] = "Unity Warp(125) brings you relatively close, and at item level you will have no issues kiting everything on your way to spawn the NM.", ["|8"] = "Take Silent Oil and Prism Powder with you and head to Kuftal Tunnel.", ["|9"] = "This fight is against Kettenkaefer, a beetle."}},
    [147] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|2"] = "Speaking with Ryoma will grant you the key item Weapons Training Guide as well as the Kodachi of Trials.", ["|6"] = "Trade the Kodachi of Trials back to Ryoma.", ["|7"] = "Take Silent Oil and Prism Powder with you and head to the Labyrinth of Onzozo.", ["|8"] = "This fight is against Megapod Megalops, a crab.", ["|9"] = "Go back and speak with Ryoma to receive your reward."}},
    [148] = {s = {["|1"] = "Speak with Verctissa in Norg (H-9) to begin quest and obtain a Mini Tuning Fork of Water.", ["|2"] = "You may prepare for the upcoming battle and whenever you are ready, trade Verctissa the tuning fork to be transported to the arena.", ["|3"] = "Trade the fork to the Water Protocrystal to enter the fighting arena.", ["|4"] = "Defeat Leviathan Prime to complete quest."}},
    [149] = {s = {["|1"] = "Speak to Stray Cloud for a cutscene.", ["|2"] = "Head towards Sea Serpent Grotto, you will get another cutscene shortly before you reach the zoneline.", ["|3"] = "Once inside Sea Serpent Grotto, head to (K-6) where you will find a ???.", ["|4"] = "Check the ??? to spawn Glyryvilu.", ["|5"] = "Defeat Glyryvilu, then check the ??? again to receive the Caliginous Blade.", ["|6"] = "Return to Stray Cloud for your reward."}},
    [162] = {s = {["|1"] = "Touch the Cermet Headstone with the key item in your posession after completing Zilart Mission 7."}},
    [163] = {s = {["|1"] = "Enter The Shrine of Ru'Avitau from the (H-9) entrance in Ru'Aun Gardens.", ["|10"] = "The general strategy at level 75 was to divide and conquer.", ["|11"] = "Once you have finished the battle, return to the Blank Target in The Shrine of Ru'Avitau to choose your reward.", ["|2"] = "Head North a short distance to find a Blank Target at (G/H-11).", ["|3"] = "Examine the Blank Target for a cutscene.", ["|4"] = "Examine the Blank Target again for dialogue about how to obtain an Ark Pentasphere.", ["|5"] = "You, or someone in your group, will need to obtain an Ark Pentasphere.", ["|6"] = "Trade the Ark Pentasphere to any of the Shimmering Circles in La'Loff Amphitheater to access the battlefield.", ["|7"] = "This battle has a 30 minute time limit and allows for a full alliance of 18 people will be allowed to enter.", ["|8"] = "You will need to defeat Ark Angel MR, Ark Angel TT, Ark Angel EV, Ark Angel HM, and Ark Angel GK in order to win.", ["|9"] = "If you happen to have an alliance wipe, re-raise, heal, and then finish off whoever remains."}},
    [164] = {s = {["|12"] = "Drop your current earring.", ["|13"] = "Receive the quest at the unmarked target (G/H-11) in the main entrance of The Shrine of Ru'Avitau.", ["|14"] = "The quest appears as a second Divine Might quest in your quest log with a different description.", ["|15"] = "Obtain a Light Ore.", ["|16"] = "If you need a new Ark Pentasphere (an already used one will no longer work - \"The Illuminink on the ark pentasphere has faded.\"), obtain an", ["|17"] = "Trade the Light Ore to the Qu'Hau Spring in Ro'Maeve during a Full Moon between 18:00 and 6:00 to receive the Moonlight ore.", ["|18"] = "Trade the Illuminink and Parchment to the Qu'Hau Spring in Ro'Maeve during a Full Moon between 18:00 and 6:00 to obtain an Ark Pentasphere.", ["|19"] = "Enter and complete the Divine Might battlefield at La'Loff Amphitheater.", ["|20"] = "Return to the unmarked target in The Shrine of Ru'Avitau to pick up a new earring."}},
    [165] = {s = {["|1"] = "Speak to Lokpix in Eastern Altepa Desert at (G-7).", ["|2"] = "You may find Unity Warp 125 to Quicksand Caves helpful to reach the Cloister of Tremors containing the Tremorstone in the west part of the", ["|3"] = "Trade him the items at the same time to receive your reward."}},
    [192] = {s = {["|1"] = "Speak to Edigey to begin this quest.", ["|2"] = "Desert Venom drops off Doom Scorpions in Eastern Altepa Desert, Tulwar Scorpions in Western Altepa Desert, or purchased off the Auction", ["|3"] = "Trade the Desert Venom to Edigey for your reward."}},
    [193] = {s = {["|1"] = "Speak to Alfesar who asks you to help him find an Ancient tablet fragment.", ["|2"] = "The Ancient tablet fragment is found by checking one of 5 ???s in the Quicksand Caves.", ["|3"] = "Return to Alfesar who gives you Tablet of ancient magic and Letter from Alfesar.", ["|4"] = "Speak to Charlaimagnat, Northern San d'Oria (M-7).", ["|5"] = "Zone and return to Charlaimagnat after one earth minute for your reward."}},
    [194] = {s = {["|1"] = "Speak with Agado-Pugado to obtain quest.", ["|2"] = "Travel to Cape Teriggan (F-5) to enter the Cloister of Gales.", ["|3"] = "Defeat Garuda Prime and you will receive a Whisper of gales.", ["|4"] = "Return to Agado-Pugado with the whisper and she will provide several reward options including the ability to summon Garuda (Avatar)."}},
    [195] = {s = {["|1"] = "Speak to Datta to begin the quest.", ["|2"] = "Form a party with at least 2 people below level 40.", ["|3"] = "Head to Kuftal Tunnel and examine the ??? near the entrance for a cutscene.", ["|4"] = "Once you get the cutscene in Kuftal Tunnel, return to Datta for your reward."}},
    [197] = {s = {["|1"] = "Speak with Rahi Fohlatti in Rabao (G-9) to begin quest and obtain a Mini Tuning Fork of Wind.", ["|2"] = "You may prepare for the upcoming battle and whenever you are ready, trade Rahi Fohlatti the tuning fork to be transported to the arena.", ["|3"] = "Trade the fork to the Wind Protocrystal to enter the fighting arena.", ["|4"] = "Defeat Garuda Prime to complete quest."}},
    [199] = {s = {["|1"] = "First head to Rabao and talk to Rudolfo (J-7).", ["|10"] = "Head to Selbina and talk to Abelard at G-9).", ["|11"] = "Use the Swirling Vortex in Valkurm Dunes in the cave at (I-9) to Lufaise Meadows.", ["|12"] = "You will get a cut scene when you zone into Lufaise Meadows.", ["|13"] = "Head to Rabao, talk to Zoriboh (F-6).", ["|2"] = "Talk to Zoriboh (F-6).", ["|3"] = "Head to Norg and talk to Sohyon (J-8).", ["|4"] = "Then talk to Washu to receive the Key Item: Washu's flask.", ["|5"] = "Head to Korroloka Tunnel.", ["|6"] = "Head to Norg and talk to Sohyon (J-8) to receive the Storeroom key.", ["|7"] = "Talk to Gimb (H-9).", ["|8"] = "Head to Port Bastok and talk to Kagetora (F-6).", ["|9"] = "Trade 5x Eastern Gems to Patient Wheel (F-5)."}},
    [201] = {s = {["|1"] = "To begin this quest in your log, you need the Serpent Rumors key item.", ["|2"] = "Turn in Liks and Gugrusaurus to Zaldon to obtain Opal Silk and Saber Shoot, respectively.", ["|3"] = "Speak to Irmilant in Rabao (G-7).", ["|4"] = "Trade the Opal Silk and Saber Shoot to Irmilant.", ["|5"] = "Return to Irmilant after conquest tally to receive your reward."}},
    [202] = {s = {["|1"] = "Doing the quest Fisherman's Heart, will allow you to see how many unique fish you have caught, by talking to Katsunaga in Mhaura.", ["|2"] = "Talk to Irmilant to start the quest.", ["|3"] = "You will need to catch, in any order, the following 5 Legendary fish.", ["|4"] = "If you have already caught one of these legendary fish prior to activating this quest, (see Katsunaga in Mhaura to check) you may purchase", ["|5"] = "After you trade in all five, trade your Ebisu Fishing Rod to him in order to upgrade it."}},
    [203] = {s = {["|1"] = "Speak to Jourdenaux while in possession of a Lu Shang's Fishing Rod to flag this quest.", ["|2"] = "This will unlock a new Records of Eminence category \"Fishing > Fishing (Tenacity)\"", ["|3"] = "You must now do the following:", ["|4"] = "After completing all of the objectives, trade your Lu Shang's Fishing Rod to Jourdenaux to complete the quest and for your reward."}},
